window.bookSummaryJSON = "<i>New York Times</i> best-selling author Charlaine Harris is a fan favorite for her Sookie Stackhouse mysteries as well as this series, starring supernatural detective Harper Connelly. <p> Called to tiny Doraville, North Carolina, Harper investigates the disappearance of several young boys. After finding them buried in a secluded wood, it becomes clear that a sadistic serial killer is stalking the town's children.</p>"; 
